'use strict';

import isAbsoluteURL from '../helpers/isAbsoluteURL.js';
import combineURLs from '../helpers/combineURLs.js';

/**
 * Creates a new URL by combining the baseURL with the requestedURL,
 * only when the requestedURL is not already an absolute URL.
 * If the requestURL is absolute, this function returns the requestedURL untouched.
 *
 * @param {string} baseURL The base URL
 * @param {string} requestedURL Absolute or relative URL to combine
 *
 * @returns {string} The combined full path
 */
export default function buildFullPath(baseURL, requestedURL) {
  if (baseURL && !isAbsoluteURL(requestedURL)) {
    return combineURLs(baseURL, requestedURL);
  }
  return requestedURL;
}
'use strict';

import { ProtocolReader } from './parseProtocol.js';

/**
 * Determines whether the specified URL is absolute
 *
 * @param {string} url The URL to test
 *
 * @returns {boolean} True if the specified URL is absolute, otherwise false
 */
class AbsoluteURL {
  constructor() {
    this.schemePattern = /^[a-z][a-z\d+\-.]*$/i;
    this.authorityPrefix = '//';
  }

  isAbsolute(candidate) {
    if (candidate.length < this.authorityPrefix.length) {
      return false;
    }

    // A URL is considered absolute if it begins with "<scheme>://" or "//" (protocol-relative URL).
    // RFC 3986 defines scheme name as a sequence of characters beginning with a letter and followed
    // by any combination of letters, digits, plus, period, or hyphen.
    if (candidate.firstChar === this.authorityPrefix.charAt(0) &&
        candidate.secondChar === this.authorityPrefix.charAt(1)) {
      return true;
    }

    if (!candidate.schemeName || !this.schemePattern.test(candidate.schemeName)) {
      return false;
    }

    return candidate.afterScheme.charAt(0) === this.authorityPrefix.charAt(0) &&
      candidate.afterScheme.charAt(1) === this.authorityPrefix.charAt(1);
  }
}

const protocolReader = new ProtocolReader();
const absoluteURL = new AbsoluteURL();

export default function isAbsoluteURL(url) {
  return absoluteURL.isAbsolute(protocolReader.read(url));
}
'use strict';

/**
 * Creates a new URL by combining the specified URLs
 *
 * @param {string} baseURL The base URL
 * @param {string} relativeURL The relative URL
 *
 * @returns {string} The combined URL
 */
export default function combineURLs(baseURL, relativeURL) {
  return relativeURL
    ? baseURL.replace(/\/?\/$/, '') + '/' + relativeURL.replace(/^\/+/, '')
    : baseURL;
}
'use strict';

import { HrefParts } from '../platform/common/utils.js';

export default function parseProtocol(url) {
  const match = /^([-+\w]{1,25})(:?\/\/|:)/.exec(url);
  return match && match[1] || '';
}

export class ProtocolReader {
  read(url) {
    const parts = new HrefParts(url);
    const colonIndex = parts.raw.indexOf(':');

    if (colonIndex > 0) {
      parts.schemeName = parts.raw.slice(0, colonIndex);
      parts.afterScheme = parts.raw.slice(colonIndex + 1);
    }

    return parts;
  }
}

